// and trusted clusters
func TestMigrateOSS(t *testing.T) {
	ctx := context.Background()
	newServer := func(t *testing.T, name ...string) *Server {
		t.Helper()
		as := newTestAuthServer(t, name...)
		require.NoError(t, as.CreateRole(services.NewAdminRole()))
		return as
	}

	t.Run("EmptyCluster", func(t *testing.T) {
		as := newServer(t)
		clock := clockwork.NewFakeClock()
		as.SetClock(clock)

		err := migrateOSS(ctx, as)
		require.NoError(t, err)

		// Second call should not fail
		err = migrateOSS(ctx, as)
		require.NoError(t, err)

		// The existing admin role was downgraded in place.
		role, err := as.GetRole(teleport.AdminRoleName)
		require.NoError(t, err)
		require.Equal(t, types.True, role.GetMetadata().Labels[teleport.OSSMigratedV6])
		require.Equal(t, []services.Rule{
			services.NewRule(services.KindEvent, services.RO()),
			services.NewRule(services.KindSession, services.RO()),
		}, role.GetRules(services.Allow))
		_, err = as.GetRole(teleport.OSSUserRoleName)
		require.True(t, trace.IsNotFound(err))
	})

	t.Run("User", func(t *testing.T) {
		as := newServer(t)
		clock := clockwork.NewFakeClock()
		as.SetClock(clock)

		user, _, err := CreateUserAndRole(as, "alice", []string{"alice"})
		require.NoError(t, err)
		// An earlier 6.0 migration may already have labeled users while assigning
		// them to ossuser. They still need to be moved back to admin.
		previouslyMigrated, err := services.NewUser("bob")
		require.NoError(t, err)
		previouslyMigrated.SetRoles([]string{teleport.OSSUserRoleName})
		meta := previouslyMigrated.GetMetadata()
		meta.Labels = map[string]string{teleport.OSSMigratedV6: types.True}
		previouslyMigrated.SetMetadata(meta)
		require.NoError(t, as.UpsertUser(previouslyMigrated))

		err = migrateOSS(ctx, as)
		require.NoError(t, err)

		out, err := as.GetUser(user.GetName(), false)
		require.NoError(t, err)
		require.Equal(t, []string{teleport.AdminRoleName}, out.GetRoles())
		require.Equal(t, types.True, out.GetMetadata().Labels[teleport.OSSMigratedV6])
		out, err = as.GetUser(previouslyMigrated.GetName(), false)
		require.NoError(t, err)
		require.Equal(t, []string{teleport.AdminRoleName}, out.GetRoles())
		require.Equal(t, types.True, out.GetMetadata().Labels[teleport.OSSMigratedV6])

		err = migrateOSS(ctx, as)
		require.NoError(t, err)
	})

	t.Run("TrustedCluster", func(t *testing.T) {
		clusterName := "test.localhost"
		as := newServer(t, clusterName)
		clock := clockwork.NewFakeClock()
		as.SetClock(clock)

		oldMapping := types.RoleMap{{Remote: remoteWildcardPattern, Local: []string{teleport.OSSUserRoleName}}}
		for _, name := range []string{"foo", "already-migrated"} {
			tc, err := services.NewTrustedCluster(name, services.TrustedClusterSpecV2{
				Enabled:              false,
				Token:                "qux",
				ProxyAddress:         "quux",
				ReverseTunnelAddress: "quuz",
			})
			require.NoError(t, err)
			if name == "already-migrated" {
				meta := tc.GetMetadata()
				meta.Labels = map[string]string{teleport.OSSMigratedV6: types.True}
				tc.SetMetadata(meta)
				tc.SetRoleMap(oldMapping)
			}
			value, err := services.MarshalTrustedCluster(tc)
			require.NoError(t, err)
			_, err = as.bk.Put(ctx, backend.Item{
				Key:   []byte("/trustedclusters/" + name),
				Value: value,
			})
			require.NoError(t, err)
		}

		for _, name := range []string{clusterName, "foo", "already-migrated"} {
			for _, catype := range []services.CertAuthType{services.UserCA, services.HostCA} {
				causer := suite.NewTestCA(catype, name)
				if name == "already-migrated" {
					meta := causer.GetMetadata()
					meta.Labels = map[string]string{teleport.OSSMigratedV6: types.True}
					causer.SetMetadata(meta)
					causer.SetRoleMap(oldMapping)
				}
				err := as.UpsertCertAuthority(causer)
				require.NoError(t, err)
			}
		}

		err = migrateOSS(ctx, as)
		require.NoError(t, err)

		mapping := types.RoleMap{{Remote: remoteWildcardPattern, Local: []string{teleport.AdminRoleName}}}
		for _, name := range []string{"foo", "already-migrated"} {
			out, err := as.GetTrustedCluster(name)
			require.NoError(t, err)
			require.Equal(t, mapping, out.GetRoleMap())
			require.Equal(t, types.True, out.GetMetadata().Labels[teleport.OSSMigratedV6])
			for _, catype := range []services.CertAuthType{services.UserCA, services.HostCA} {
				ca, err := as.GetCertAuthority(services.CertAuthID{Type: catype, DomainName: name}, true)
				require.NoError(t, err)
				require.Equal(t, mapping, ca.GetRoleMap())
				require.Equal(t, types.True, ca.GetMetadata().Labels[teleport.OSSMigratedV6])
			}
		}

